   250	        else if ( gem.nullValuePropertyMappingStrategy().hasValue() && gem.constant().hasValue() ) {
   251	            message = Message.PROPERTYMAPPING_CONSTANT_VALUE_AND_NVPMS;
   252	        }
   253	        else if ( gem.nullValuePropertyMappingStrategy().hasValue() && gem.expression().hasValue() ) {
   254	            message = Message.PROPERTYMAPPING_EXPRESSION_VALUE_AND_NVPMS;
   255	        }
   256	        else if ( gem.nullValuePropertyMappingStrategy().hasValue() && gem.defaultExpression().hasValue() ) {
   257	            message = Message.PROPERTYMAPPING_DEFAULT_EXPERSSION_AND_NVPMS;
   258	        }
   259	        else if ( gem.nullValuePropertyMappingStrategy().hasValue()
   260	            && gem.ignore().hasValue() && gem.ignore().getValue() ) {
   260	            && gem.ignore().hasValue() && gem.ignore().getValue() ) {
   261	            message = Message.PROPERTYMAPPING_IGNORE_AND_NVPMS;
   262	        }
   263	        else if ( ".".equals( gem.target().get() ) && gem.ignore().hasValue() && gem.ignore().getValue() ) {
   264	            message = Message.PROPERTYMAPPING_TARGET_THIS_AND_IGNORE;
   265	        }
   266	        else if ( ".".equals( gem.target().get() ) && !gem.source().hasValue() ) {
   267	            message = Message.PROPERTYMAPPING_TARGET_THIS_NO_SOURCE;
   268	        }
   269	
   270	        if ( message == null ) {
   271	            return true;
   272	        }
   273	        else {
   274	            messager.printMessage( method, gem.mirror(), message );
   275	            return false;
   276	        }
   277	    }
