   317	    private static String getExpression(MappingGem mapping, ExecutableElement element,
   318	                                        FormattingMessager messager) {
   319	        if ( !mapping.expression().hasValue() ) {
   320	            return null;
   321	        }
   322	
   323	        Matcher javaExpressionMatcher = JAVA_EXPRESSION.matcher( mapping.expression().get() );
   324	
   325	        if ( !javaExpressionMatcher.matches() ) {
   326	            messager.printMessage(
   327	                element,
   328	                mapping.mirror(),
   329	                mapping.expression().getAnnotationValue(),
   330	                Message.PROPERTYMAPPING_INVALID_EXPRESSION
   331	            );
   332	            return null;
   333	        }
   334	
   335	        return javaExpressionMatcher.group( 1 ).trim();
   336	    }
