   149	    /**
   150	     * Merges in all the mapping options configured, giving the already defined options precedence.
   151	     *
   152	     * @param sourceMethod the method which inherits the options.
   153	     * @param templateMethod the template method with the options to inherit, may be {@code null}
   154	     * @param isInverse if {@code true}, the specified options are from an inverse method
   155	     * @param annotationMirror the annotation on which the compile errors will be shown.
   156	     */
   157	    public void applyInheritedOptions(SourceMethod sourceMethod, SourceMethod templateMethod, boolean isInverse,
   158	                                      AnnotationMirror annotationMirror) {
   159	        MappingMethodOptions templateOptions = templateMethod.getOptions();
   160	        if ( null != templateOptions ) {
   161	            if ( !getIterableMapping().hasAnnotation() && templateOptions.getIterableMapping().hasAnnotation() ) {
   162	                setIterableMapping( templateOptions.getIterableMapping() );
   163	            }
   164	
   165	            if ( !getMapMapping().hasAnnotation() && templateOptions.getMapMapping().hasAnnotation() ) {
   166	                setMapMapping( templateOptions.getMapMapping() );
   167	            }
   168	
   169	            if ( !getBeanMapping().hasAnnotation() && templateOptions.getBeanMapping().hasAnnotation() ) {
   170	                setBeanMapping( BeanMappingOptions.forInheritance( templateOptions.getBeanMapping( ), isInverse ) );
   171	            }
   172	
   173	            if ( !getEnumMappingOptions().hasAnnotation() && templateOptions.getEnumMappingOptions().hasAnnotation() ) {
   174	                EnumMappingOptions newEnumMappingOptions;
   175	                if ( isInverse ) {
   176	                    newEnumMappingOptions = templateOptions.getEnumMappingOptions().inverse();
   177	                }
   178	                else {
   179	                    newEnumMappingOptions = templateOptions.getEnumMappingOptions();
   180	                }
   181	                setEnumMappingOptions( newEnumMappingOptions );
   182	            }
   183	
   184	            if ( getValueMappings() == null ) {
   185	                if ( templateOptions.getValueMappings() != null ) {
   186	                    // there were no mappings, so the inherited mappings are the new ones
   187	                    setValueMappings( templateOptions.getValueMappings() );
   188	                }
   189	                else {
   190	                    setValueMappings( Collections.emptyList() );
   191	                }
   192	            }
   193	            else {
   194	                if ( templateOptions.getValueMappings() != null ) {
   195	                    // if there are also inherited mappings, we inverse and add them.
   196	                    for ( ValueMappingOptions inheritedValueMapping : templateOptions.getValueMappings() ) {
   197	                        ValueMappingOptions valueMapping =
   198	                            isInverse ? inheritedValueMapping.inverse() : inheritedValueMapping;
   199	                        if ( valueMapping != null
   200	                            && !getValueMappings().contains(  valueMapping ) ) {
   201	                            getValueMappings().add( valueMapping );
   202	                        }
   203	                    }
   204	                }
   205	            }
   206	
   207	            if ( isInverse ) {
   208	                List<SubclassMappingOptions> inheritedMappings = SubclassMappingOptions.copyForInverseInheritance(
   209	                                              templateOptions.getSubclassMappings(),
   210	                                              getBeanMapping() );
   211	                addAllNonRedefined( sourceMethod, annotationMirror, inheritedMappings );
   212	            }
   213	            else if ( methodsHaveIdenticalSignature( templateMethod, sourceMethod ) ) {
   214	                List<SubclassMappingOptions> inheritedMappings =
   215	                    SubclassMappingOptions
   216	                                          .copyForInheritance(
   217	                                              templateOptions.getSubclassMappings(),
   218	                                              getBeanMapping() );
   219	                addAllNonRedefined( sourceMethod, annotationMirror, inheritedMappings );
   220	            }
   221	
   222	            Set<MappingOptions> newMappings = new LinkedHashSet<>();
   223	            for ( MappingOptions mapping : templateOptions.getMappings() ) {
   224	                if ( isInverse ) {
   225	                    if ( mapping.canInverse() ) {
   226	                        newMappings.add( mapping.copyForInverseInheritance( templateMethod, getBeanMapping() ) );
   227	                    }
   228	                }
   229	                else {
   230	                    newMappings.add( mapping.copyForForwardInheritance( templateMethod, getBeanMapping() ) );
   231	                }
   232	            }
   233	
   234	            // now add all (does not override duplicates and leaves original mappings)
   235	            addAllNonRedefined( newMappings );
   236	
   237	            // filter new mappings
   238	            filterNestedTargetIgnores( mappings );
   239	        }
   240	    }
