   242	    private boolean methodsHaveIdenticalSignature(SourceMethod templateMethod, SourceMethod sourceMethod) {
   243	        return parametersAreOfIdenticalTypeAndOrder( templateMethod, sourceMethod )
   244	            && resultTypeIsTheSame( templateMethod, sourceMethod );
   245	    }
   246	
   247	    private boolean parametersAreOfIdenticalTypeAndOrder(SourceMethod templateMethod, SourceMethod sourceMethod) {
   248	        if ( templateMethod.getParameters().size() != sourceMethod.getParameters().size() ) {
   249	            return false;
   250	        }
   251	        for ( int i = 0; i < templateMethod.getParameters().size(); i++ ) {
   252	            if ( !templateMethod.getParameters().get( i ).getType().equals(
   253	                                       sourceMethod.getParameters().get( i ).getType() ) ) {
   254	                return false;
   255	            }
   256	        }
   257	        return true;
   258	    }
