   260	    private boolean resultTypeIsTheSame(SourceMethod templateMethod, SourceMethod sourceMethod) {
   260	    private boolean resultTypeIsTheSame(SourceMethod templateMethod, SourceMethod sourceMethod) {
   261	        return templateMethod.getResultType().equals( sourceMethod.getResultType() );
   262	    }
