   264	    private void addAllNonRedefined(SourceMethod sourceMethod, AnnotationMirror annotationMirror,
   265	                                    List<SubclassMappingOptions> inheritedMappings) {
   266	        Set<SubclassMappingOptions> redefinedSubclassMappings = new HashSet<>( subclassMappings );
   267	        for ( SubclassMappingOptions subclassMappingOption : inheritedMappings ) {
   268	            if ( !redefinedSubclassMappings.contains( subclassMappingOption ) ) {
   269	                if ( subclassValidator.isValidUsage(
   270	                                          sourceMethod.getExecutable(),
   271	                                          annotationMirror,
   272	                    subclassMappingOption.getSource() ) ) {
   273	                    subclassMappings.add( subclassMappingOption );
   274	                }
   275	            }
   276	        }
   277	    }
