    private Set<MappingOptions> getInheritedSuperMappings(DeclaredType includingType,
                                                           TypeElement overrideContextType,
                                                           ExecutableElement method,
                                                           List<Parameter> parameters,
                                                           BeanMappingOptions beanMappingOptions,
                                                           BeanMappingGem beanMapping,
                                                           Set<MappingOptions> declaredMappings) {
        List<ExecutableElement> overriddenMethods = new ArrayList<>();
        collectOverriddenMappingMethods(
            method,
            (TypeElement) method.getEnclosingElement(),
            overrideContextType,
            new HashSet<>(),
            overriddenMethods
        );

        if ( overriddenMethods.isEmpty() ) {
            messager.printMessage(
                method,
                beanMapping.mirror(),
                beanMapping.inheritSuperMappings().getAnnotationValue(),
                Message.BEANMAPPING_INHERIT_SUPER_MAPPINGS_NO_SUPER
            );
            return Collections.emptySet();
        }

        Set<String> declaredTargets = new HashSet<>();
        for ( MappingOptions declaredMapping : declaredMappings ) {
            if ( !".".equals( declaredMapping.getTargetName() ) ) {
                declaredTargets.add( declaredMapping.getTargetName() );
            }
        }

        Set<MappingOptions> inheritedMappings = new LinkedHashSet<>();
        Map<String, List<SuperMapping>> mappingsByTarget = new LinkedHashMap<>();
        for ( ExecutableElement overriddenMethod : overriddenMethods ) {
            ExecutableType overriddenMethodType = typeFactory.getMethodType( includingType, overriddenMethod );
            List<Parameter> overriddenParameters = typeFactory.getParameters(
                overriddenMethodType,
                overriddenMethod
            );
            Set<MappingOptions> mappings = getMappings( overriddenMethod, beanMappingOptions );
            for ( MappingOptions mapping : mappings ) {
                String sourceName = rebindSuperMappingSource(
                    mapping.getSourceName(),
                    overriddenParameters,
                    parameters
                );
                MappingOptions inheritedMapping = mapping.copyForSuperInheritance(
                    sourceName,
                    beanMappingOptions
                );
                String targetName = mapping.getTargetName();
                if ( ".".equals( targetName ) ) {
                    inheritedMappings.add( inheritedMapping );
                }
                else if ( !declaredTargets.contains( targetName ) ) {
                    mappingsByTarget.computeIfAbsent( targetName, key -> new ArrayList<>() )
                        .add( new SuperMapping( overriddenMethod, inheritedMapping ) );
                }
            }
        }

        for ( Map.Entry<String, List<SuperMapping>> entry : mappingsByTarget.entrySet() ) {
            List<SuperMapping> mostSpecificMappings = getMostSpecificMappings(
                entry.getValue()
            );
            if ( mostSpecificMappings.size() == 1 ) {
                inheritedMappings.add( mostSpecificMappings.get( 0 ).mapping );
            }
            else {
                Set<String> declaringTypes = new LinkedHashSet<>();
                for ( SuperMapping mostSpecificMapping : mostSpecificMappings ) {
                    TypeElement declaringType = (TypeElement) mostSpecificMapping.method.getEnclosingElement();
                    declaringTypes.add( declaringType.getQualifiedName().toString() );
                }
                messager.printMessage(
                    method,
                    beanMapping.mirror(),
                    beanMapping.inheritSuperMappings().getAnnotationValue(),
                    Message.BEANMAPPING_INHERIT_SUPER_MAPPINGS_AMBIGUOUS,
                    entry.getKey(),
                    Strings.join( declaringTypes, ", " )
                );
            }
        }

        return inheritedMappings;
    }

    private void collectOverriddenMappingMethods(ExecutableElement method,
                                                 TypeElement declaringType,
                                                 TypeElement overrideContextType,
                                                 Set<ExecutableElement> visitedMethods,
                                                 List<ExecutableElement> overriddenMethods) {
        for ( TypeMirror supertype : typeUtils.directSupertypes( declaringType.asType() ) ) {
            Element supertypeElement = typeUtils.asElement( supertype );
            if ( !( supertypeElement instanceof TypeElement ) ) {
                continue;
            }

            TypeElement supertypeDeclaration = (TypeElement) supertypeElement;
            for ( ExecutableElement candidate : ElementFilter.methodsIn( supertypeDeclaration.getEnclosedElements() ) ) {
                if ( candidate.getModifiers().contains( Modifier.ABSTRACT )
                    && elementUtils.overrides( method, candidate, overrideContextType )
                    && visitedMethods.add( candidate ) ) {
                    overriddenMethods.add( candidate );
                }
            }
            collectOverriddenMappingMethods(
                method,
                supertypeDeclaration,
                overrideContextType,
                visitedMethods,
                overriddenMethods
            );
        }
    }

    private List<SuperMapping> getMostSpecificMappings(List<SuperMapping> mappings) {
        List<SuperMapping> mostSpecificMappings = new ArrayList<>();
        for ( SuperMapping candidate : mappings ) {
            boolean overridden = false;
            for ( SuperMapping other : mappings ) {
                TypeElement candidateDeclaringType = (TypeElement) candidate.method.getEnclosingElement();
                TypeElement otherDeclaringType = (TypeElement) other.method.getEnclosingElement();
                if ( candidate != other
                    && typeUtils.isSubtypeErased( otherDeclaringType.asType(), candidateDeclaringType.asType() ) ) {
                    overridden = true;
                    break;
                }
            }
            if ( !overridden ) {
                mostSpecificMappings.add( candidate );
            }
        }
        return mostSpecificMappings;
    }

